     "title": "美军称对伊朗目标发动新一轮打击",
     "url": "http://finance.eastmoney.com/news/1351,202609023861896968.html",
     "time": "09-02 02:30",
     "ts": 1788287413,
     "summary": "美军中央司令部1日在社交媒体发布消息说，美军于美东时间1日12时开始对伊朗境内的伊朗伊斯兰革命卫队目标发动新一轮打击。 消息称，伊朗伊斯兰革命卫队曾企图袭击霍尔木兹海峡商船以及部署在该地区的美军人员。但消息没有说明美军此次打击的具体地点。 据伊朗媒体1日报道，伊朗南部格什姆岛及霍尔木兹海峡一带当晚传出多次爆炸声。目前尚无人员伤亡或设施受损的报告。 美军中央司令部8月30日发表声明说，美军对伊朗伊斯兰革命卫队的布雷部队采取了“有限精准”行动，并指责其对霍尔木兹海峡航行安全构成威",
